<script type="application/ld+json">
{"@context": "https://schema.org", "@type": "FAQPage", "mainEntity": [{"@type": "Question", "name": "Куда подавать исполнительный лист, если должник — государственное учреждение?", "acceptedAnswer": {"@type": "Answer", "text": "В орган, ведущий его лицевые счета: для федеральных казённых учреждений и органов власти — территориальный орган Федерального казначейства по месту открытия лицевого счёта (ст. 242.3 БК), для учреждений субъекта — финорган региона (ст. 242.4), для муниципальных — финорган муниципалитета (ст. 242.5)."}}, {"@type": "Question", "name": "Почему приставы вернули исполнительный лист на бюджетное учреждение?", "acceptedAnswer": {"@type": "Answer", "text": "Из-за иммунитета бюджетов: ст. 239 БК исключает обращение взыскания на бюджетные средства в общем порядке Закона № 229-ФЗ. Исполнение идёт по главе 24.1 БК через казначейство или финорган. Приставы подключаются только к счетам учреждений в банках, если такие есть."}}, {"@type": "Question", "name": "Какие документы нужны для подачи в казначейство?", "acceptedAnswer": {"@type": "Answer", "text": "По п. 2 ст. 242.1 БК: подлинник исполнительного листа (или судебного приказа), копия судебного акта, заверенная судом, и заявление взыскателя с реквизитами банковского счёта для перечисления. Представителю — доверенность с соответствующими полномочиями."}}, {"@type": "Question", "name": "Сколько ждать денег после подачи документов?", "acceptedAnswer": {"@type": "Answer", "text": "Нормативный срок исполнения — 3 месяца со дня поступления полного комплекта. На практике многие должники платят раньше: после уведомления у них 10 рабочих дней на представление платёжного документа, а за просрочку казначейство блокирует их лицевые счета."}}, {"@type": "Question", "name": "Что будет, если должник не заплатит за 3 месяца?", "acceptedAnswer": {"@type": "Answer", "text": "Орган казначейства приостанавливает операции по расходованию средств на всех лицевых счетах должника, включая структурные подразделения, — до исполнения требований. Учреждение с заблокированной расходной частью не может вести деятельность, поэтому блокировка почти всегда приводит к оплате."}}, {"@type": "Question", "name": "Можно ли взыскать через казначейство неустойку и судебные расходы?", "acceptedAnswer": {"@type": "Answer", "text": "Да — всё, что присуждено судебным актом: основной долг, пени, штрафы, госпошлину, судебные расходы. Пени за период после решения и индексацию по ст. 183 АПК можно просудить отдельно и предъявить вторым листом по той же процедуре."}}, {"@type": "Question", "name": "Деньги придут на лицевой счёт или на расчётный?", "acceptedAnswer": {"@type": "Answer", "text": "На банковский счёт, указанный в заявлении взыскателя. Взысканный долг — исполнение судебного акта, а не целевые средства контракта, поэтому казначейское сопровождение на него не распространяется."}}, {"@type": "Question", "name": "Что делать, если у казённого учреждения нет лимитов?", "acceptedAnswer": {"@type": "Answer", "text": "Должник обязан запросить лимиты у главного распорядителя. Если исполнение затягивается, взыскатель предъявляет иск о субсидиарной ответственности к собственнику имущества учреждения (п. 4 ст. 123.22 ГК) — дальше взыскание идёт с казны по ст. 242.2 БК."}}, {"@type": "Question", "name": "Отвечает ли учредитель по долгам бюджетного учреждения?", "acceptedAnswer": {"@type": "Answer", "text": "По контрактным долгам бюджетного учреждения собственник по общему правилу субсидиарной ответственности не несёт — в отличие от казённого. Поэтому тип учреждения-заказчика стоит проверять ещё на стадии заключения контракта."}}, {"@type": "Question", "name": "Действует ли этот порядок, если контракт шёл через казначейское сопровождение?", "acceptedAnswer": {"@type": "Answer", "text": "Да. Долг заказчика за принятое исполнение — обычное денежное обязательство, и взыскивается он по главе 24.1 БК независимо от того, как велись расчёты. Важно лишь не путать долг с задержкой санкционирования платежа — это операционная проблема, решаемая без суда."}}, {"@type": "Question", "name": "Каков срок предъявления исполнительного листа?", "acceptedAnswer": {"@type": "Answer", "text": "Три года со дня вступления судебного акта в законную силу (ст. 321 АПК, ст. 21 Закона № 229-ФЗ). Пропущенный срок — основание возврата документов; восстанавливается только судом по уважительным причинам."}}, {"@type": "Question", "name": "Можно ли подать документы в казначейство в электронном виде?", "acceptedAnswer": {"@type": "Answer", "text": "Базовый порядок — подлинник листа на бумаге, лично или почтой. Суд по ходатайству взыскателя может направить лист на исполнение самостоятельно. Уточняйте актуальные каналы подачи в своём ТОФК или финоргане — практика электронного взаимодействия расширяется."}}]}
</script>
<script type="application/ld+json">
{"@context": "https://schema.org", "@type": "HowTo", "name": "Как предъявить исполнительный лист в казначейство и получить деньги", "inLanguage": "ru-RU", "step": [{"@type": "HowToStep", "position": 1, "name": "Зафиксировать долг и направить претензию", "text": "Свериться со сроками оплаты (7 рабочих дней, при казначейском сопровождении — 10), рассчитать пени по ч. 5 ст. 34 Закона № 44-ФЗ и направить заказчику претензию с расчётом и сроком ответа."}, {"@type": "HowToStep", "position": 2, "name": "Взыскать долг в арбитражном суде", "text": "По истечении досудебного срока подать иск о взыскании долга и неустойки; после вступления решения в силу получить исполнительный лист."}, {"@type": "HowToStep", "position": 3, "name": "Определить орган исполнения", "text": "По типу должника выбрать адресата: ТОФК по месту лицевого счёта (федеральные казённые учреждения и органы власти), финорган субъекта или муниципалитета (региональные и местные), орган по ст. 242.2 БК — при взыскании с казны."}, {"@type": "HowToStep", "position": 4, "name": "Собрать комплект по ст. 242.1 БК", "text": "Подлинник исполнительного листа, заверенная судом копия судебного акта, заявление с банковскими реквизитами взыскателя; для представителя — доверенность. Проверить срок предъявления (3 года)."}, {"@type": "HowToStep", "position": 5, "name": "Подать документы и контролировать сроки", "text": "Направить комплект лично или ценным письмом с описью; отслеживать этапы: уведомление должника — 5 рабочих дней, ответ должника — 10 рабочих дней, исполнение — 3 месяца."}, {"@type": "HowToStep", "position": 6, "name": "Дожать при неисполнении", "text": "При нарушении срока — приостановление расходных операций по лицевым счетам должника; при отсутствии лимитов — иск о субсидиарной ответственности к собственнику казённого учреждения (п. 4 ст. 123.22 ГК), индексация и довзыскание пеней."}]}
</script>
<script type="application/ld+json">
{"@context": "https://schema.org", "@type": "DefinedTermSet", "name": "Термины: взыскание долга по госконтракту через казначейство", "inLanguage": "ru-RU", "hasDefinedTerm": [{"@type": "DefinedTerm", "name": "Иммунитет бюджетов", "description": "Правовой режим ст. 239 БК: обращение взыскания на средства бюджетов возможно только на основании судебного акта и в порядке главы 24.1 БК, вне общего исполнительного производства."}, {"@type": "DefinedTerm", "name": "Исполнительный документ", "description": "Исполнительный лист или судебный приказ, выданный судом на основании вступившего в силу судебного акта; предъявляется к исполнению в течение трёх лет."}, {"@type": "DefinedTerm", "name": "Казённое учреждение", "description": "Государственное или муниципальное учреждение, финансируемое по бюджетной смете; по его денежным обязательствам при недостатке средств субсидиарно отвечает собственник имущества (п. 4 ст. 123.22 ГК)."}, {"@type": "DefinedTerm", "name": "Главный распорядитель бюджетных средств (ГРБС)", "description": "Орган, распределяющий лимиты бюджетных обязательств подведомственным учреждениям; ответчик по субсидиарным искам и искам к казне."}, {"@type": "DefinedTerm", "name": "Лимиты бюджетных обязательств", "description": "Объём прав казённого учреждения на принятие и исполнение обязательств за счёт бюджета; их недостаток — типовая причина задержки исполнения листа и повод для запроса-требования к ГРБС."}, {"@type": "DefinedTerm", "name": "Приостановление операций по лицевым счетам", "description": "Санкция за неисполнение исполнительного документа в срок: блокировка расходных операций должника до устранения нарушения (ст. 242.3–242.5 БК)."}, {"@type": "DefinedTerm", "name": "Субсидиарная ответственность", "description": "Дополнительная ответственность собственника имущества казённого учреждения по его долгам при недостаточности средств самого учреждения."}]}
